<?= $this->extend('layouts/main') ?><?= $this->section('content') ?><div class="dv-content"><div class="dv-stats-grid"><div class="dv-stat danger"><div class="dv-stat-value"><?= count(array_filter($alerts,fn($a)=>$a['niveau']>=4)) ?></div><div class="dv-stat-label">Alertes critiques</div></div><div class="dv-stat warning"><div class="dv-stat-value"><?= count($alerts) ?></div><div class="dv-stat-label">Alertes actives</div></div><div class="dv-stat info"><div class="dv-stat-value"><?= count($risks) ?></div><div class="dv-stat-label">Districts surveillés</div></div></div><div class="dv-card"><div class="dv-card-header">Carte des risques par district</div><div id="map"></div></div><div class="dv-card"><div class="dv-card-header">Alertes épidémiologiques</div><table class="dv-table"><thead><tr><th>District</th><th>Niveau</th><th>Médicament dominant</th><th>Unités</th><th>Tendance</th></tr></thead><tbody><?php foreach($alerts as $a): ?><tr><td><?= esc($a['district']) ?></td><td><?= $a['niveau'] ?>/5</td><td><?= esc($a['type_dominant']) ?></td><td><?= $a['total'] ?></td><td><?= esc($a['tendance']) ?></td></tr><?php endforeach ?></tbody></table></div></div><link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css"><script src="https://unpkg.com/leaflet@1.9.4/dist/leaflet.js"></script><style>#map{height:520px;border-radius:12px}.risk-1{fill:#cbd5e1}.risk-2{fill:#facc15}.risk-3{fill:#fb923c}.risk-4,.risk-5{fill:#ef4444}</style><script>const risks=<?= json_encode($risks) ?>,map=L.map('map').setView([-18.9,47],5.5);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© OSM'}).addTo(map);fetch('<?= base_url('assets/data/Districts.geojson') ?>').then(r=>r.json()).then(g=>L.geoJSON(g,{style:f=>{const n=f.properties.District||f.properties.NAME_2||f.properties.name||'';return{color:'#fff',weight:1,fillOpacity:.75,className:'risk-'+(risks[n]||1)}},onEachFeature:(f,l)=>{const n=f.properties.District||f.properties.NAME_2||f.properties.name||'District';l.bindPopup('<b>'+n+'</b><br>Risque : '+(risks[n]||1)+'/5')}}).addTo(map));</script><?= $this->endSection() ?>
